def wrap_count_lines(text, width):
    words = text.split()
    if not words:
        return 0
    lines = 1
    current = len(words[0])
    for word in words[1:]:
        if current + 1 + len(word) <= width:
            current += 1 + len(word)
        else:
            lines += 1
            current = len(word)
    return lines

