def distinct_prime_factors(n):
    result = []
    d = 2
    m = n
    while d * d <= m:
        if m % d == 0:
            result.append(d)
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        result.append(m)
    return result

def integer_sqrt_floor(n):
    if n < 2:
        return n
    low, high = 1, n
    while low <= high:
        mid = (low + high) // 2
        if mid * mid <= n:
            low = mid + 1
        else:
            high = mid - 1
    return high

